static const int kDrumKitDefaultsCount = 37;

// The 34 default bytes for one key of one kit, or nullptr if the kit is not
// in the table. `note` is a MIDI note number, not a row index.
inline const uint8_t* drumDefaultsFor(int msb, int lsb, int pgm, int note)
{
    if (note < kDrumDefFirstNote || note > kDrumDefLastNote) return nullptr;
    for (int i = 0; i < kDrumKitDefaultsCount; ++i)
    {
        const auto& k = kDrumKitDefaults[i];
        if (k.msb == msb && k.lsb == lsb && k.pgm == pgm)
            return kDrumDefRows[k.row[note - kDrumDefFirstNote]];
    }
    return nullptr;
}

// The row offset for a DRUM SETUP low address, or -1 if that address holds
// no stored byte (the gaps between sub-blocks, and the NOT USED tail of 20).
inline int drumDefaultOffsetForLow(uint8_t lo)
{
    for (int i = 0; i < kDrumDefSubCount; ++i)
    {
        const auto& s = kDrumDefSubs[i];
        if (lo >= s.lo && lo < s.lo + s.count) return s.offset + (lo - s.lo);
    }
    return -1;
}

